Reczne parsowanie:  petla po args, porownania String, Integer.parseInt, wlasna obsluga bledow

Picocli:            @Option(names={"-n","--name"}) String name;
                    @Option(names={"-c","--count"}) int count;
                    -- reszta (walidacja, konwersja, --help) automatyczna

@Command(name = "greet", mixinStandardHelpOptions = true, version = "greet 1.0")
class GreetCommand implements Runnable {
    @Option(names = {"-n", "--name"}, defaultValue = "Swiecie")
    String name;

    @Option(names = {"-c", "--count"}, defaultValue = "1")
    int count;

    public void run() {
        for (int i = 0; i < count; i++) System.out.println("Witaj, " + name + "!");
    }
}

@Command(name = "copy")
class CopyCommand implements Callable<Integer> {
    @Parameters(index = "0") File source;
    @Parameters(index = "1") File target;
    @Option(names = "-v") boolean verbose;

    public Integer call() {
        if (!source.exists()) { System.out.println("Blad"); return 1; }
        return 0;
    }
}

int exitCode = new CommandLine(new GreetCommand()).execute("--name", "Kasia", "--count", "3");

// BLAD: reczna walidacja obecnosci opcji zamiast required = true
@Command(name = "greet")
class GreetCommand implements Runnable {
    @Option(names = "--name")
    String name;

    public void run() {
        if (name == null) { // reczna walidacja - Picocli mogloby to zrobic za nas
            System.err.println("Opcja --name jest wymagana");
            return;
        }
        System.out.println("Witaj, " + name);
    }
}

// POPRAWNIE: required = true deleguje walidacje do Picocli
@Command(name = "greet")
class GreetCommand implements Runnable {
    @Option(names = "--name", required = true)
    String name;

    public void run() {
        System.out.println("Witaj, " + name); // name na pewno nie jest null tutaj
    }
}
